/* Stage 4A (real Mednafen .mc9 save-state BAT/VRAM/CRAM)
 *
 * Generated by tools/pack_state_window.py:
 *   stage4a_state_maps.bin : 2 screens x 32x24 plane A entries
 *   stage4a_state_tiles.bin: 303 distinct 8x8 tiles converted to MD format
 *   stage4a_state_pal.bin  : 4 MD palettes (top-used PCE palettes)
 *   player_spr.bin         : engine player test art
 */

.section .rodata
#include <macros.s>

GLABEL res_stage4a_state_tiles
.incbin "../res/gfx/stage4a_state_tiles.bin"
.align 2

GLABEL res_stage4a_state_pal
.byte 0
.byte 63
.incbin "../res/gfx/stage4a_state_pal.bin"
.align 2

GLABEL res_stage4a_state_maps
.incbin "../res/gfx/stage4a_state_maps.bin"
.align 2

GLABEL res_player_spr
.incbin "../res/gfx/player_spr.bin"
.align 2
